from torch.utils.cpp_extension import load_inline

# CUDA kernel source code for matrix multiplication with shared memory
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template<int TILE_SIZE>
__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    float sum = 0.0f;

    for (int k = 0; k < N; k += TILE_SIZE) {
        // Load tiles of A and B into shared memory
        if (row < N && (k + tx) < N) {
            sA[ty][tx] = A[row * N + k + tx];
        } else {
            sA[ty][tx] = 0.0f;
        }

        if ((k + ty) < N && col < N) {
            sB[ty][tx] = B[(k + ty) * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int i = 0; i < TILE_SIZE; i++) {
            sum += sA[ty][i] * sB[i][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int TILE_SIZE = 16;
    dim3 blockSize(TILE_SIZE, TILE_SIZE);
    dim3 gridSize((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<TILE_SIZE><<<gridSize, blockSize>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

