        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial products using register blocking
        for (int i = 0; i < TILE_SIZE; i++) {
            for (int ii = 0; ii < BLOCK_SIZE; ii++) {
                for (int jj = 0; jj < BLOCK_SIZE; jj++) {
