    float sum[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    for (int k = 0; k < N; k += TILE_SIZE) {
        // Load tiles of A and B into shared memory (each thread loads multiple elements)
        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                int load_row = ty * BLOCK_SIZE + i;
                int load_col = tx * BLOCK_SIZE + j;

